{
  "themes": [
    {
      "cluster": 12,
      "name": "Pre‑Order Delivery Delays",
      "description": "Customers report that pre‑ordered books are not shipped on time, often arriving weeks later or not at all."
    },
    {
      "cluster": 13,
      "name": "Unanswered Direct Messages",
      "description": "Users mention sending a DM or private message for help but receive no response."
    },
    {
      "cluster": 14,
      "name": "Diwali Season Delivery Failures",
      "description": "Shoppers complain that orders placed for the Diwali holiday are delayed or not delivered, causing disappointment during the festival."
    },
    {
      "cluster": 15,
      "name": "Order ID Tracking & Cancellation Issues",
      "description": "Customers struggle to get status updates, cancel orders, or receive refunds for specific order numbers."
    },
    {
      "cluster": 16,
      "name": "Poor Logistics and Courier Service",
      "description": "Feedback highlights unreliable, slow, or damaged deliveries and unhelpful courier support."
    },
    {
      "cluster": 17,
      "name": "Pricing Discrepancies and Misleading Discounts",
      "description": "Users notice mismatched MRP vs. listed price, confusing discount displays, and feel misled by price changes."
    },
    {
      "cluster": 18,
      "name": "Account Login Failures and Hacking Concerns",
      "description": "Customers cannot log in, receive password errors, or suspect account compromise."
    },
    {
      "cluster": 19,
      "name": "Locked Account After Password Changes",
      "description": "People report being locked out after multiple password resets and cannot regain access."
    },
    {
      "cluster": 20,
      "name": "Fake or Unverified Product Reviews",
      "description": "Feedback mentions suspicious review activity, inability to post reviews, and concerns about review authenticity."
    },
    {
      "cluster": 21,
      "name": "Negative Experience with India Customer Service",
      "description": "Indian shoppers describe unhelpful support, order mishandling, and perceived double standards."
    },
    {
      "cluster": 22,
      "name": "Broken Links and Site Errors",
      "description": "Users encounter error pages, broken URLs, or problems loading specific site features."
    },
    {
      "cluster": 23,
      "name": "Late or Lost Package Deliveries",
      "description": "Customers express frustration over packages arriving far later than promised, being left in unsafe locations, or disappearing entirely."
    }
  ]
}
